bool Nodes::validateJsonForCreation(const Json::Value &pJson, std::string &err)
{
    if(pJson.isMember("id"))
    {
        if(!validJsonOfField(0, "id", pJson["id"], err, true))
            return false;
    }
    if(pJson.isMember("name"))
    {
        if(!validJsonOfField(1, "name", pJson["name"], err, true))
            return false;
    }
    else
    {
        err="The name column cannot be null";
        return false;
    }
    if(pJson.isMember("public_ipv4"))
    {
        if(!validJsonOfField(2, "public_ipv4", pJson["public_ipv4"], err, true))
            return false;
    }
    else
    {
        err="The public_ipv4 column cannot be null";
        return false;
    }
    if(pJson.isMember("public_ipv6"))
    {
        if(!validJsonOfField(3, "public_ipv6", pJson["public_ipv6"], err, true))
            return false;
    }
    if(pJson.isMember("wg_ip"))
    {
        if(!validJsonOfField(4, "wg_ip", pJson["wg_ip"], err, true))
            return false;
    }
    else
    {
        err="The wg_ip column cannot be null";
        return false;
    }
    if(pJson.isMember("wg_pubkey"))
    {
        if(!validJsonOfField(5, "wg_pubkey", pJson["wg_pubkey"], err, true))
            return false;
    }
    if(pJson.isMember("is_active"))
    {
        if(!validJsonOfField(6, "is_active", pJson["is_active"], err, true))
            return false;
    }
    if(pJson.isMember("last_heartbeat_at"))
    {
        if(!validJsonOfField(7, "last_heartbeat_at", pJson["last_heartbeat_at"], err, true))
            return false;
    }
    if(pJson.isMember("health_status"))
    {
        if(!validJsonOfField(8, "health_status", pJson["health_status"], err, true))
            return false;
    }
    if(pJson.isMember("health_message"))
    {
        if(!validJsonOfField(9, "health_message", pJson["health_message"], err, true))
            return false;
    }
    if(pJson.isMember("max_users"))
    {
        if(!validJsonOfField(10, "max_users", pJson["max_users"], err, true))
            return false;
    }
    if(pJson.isMember("max_mbps"))
    {
        if(!validJsonOfField(11, "max_mbps", pJson["max_mbps"], err, true))
            return false;
    }
    if(pJson.isMember("max_sessions"))
    {
        if(!validJsonOfField(12, "max_sessions", pJson["max_sessions"], err, true))
            return false;
    }
    if(pJson.isMember("created_at"))
    {
        if(!validJsonOfField(13, "created_at", pJson["created_at"], err, true))
            return false;
    }
    if(pJson.isMember("updated_at"))
    {
        if(!validJsonOfField(14, "updated_at", pJson["updated_at"], err, true))
            return false;
    }
    return true;
}
