std::vector<NodeInbounds> Nodes::getInbounds(const DbClientPtr &clientPtr) const {
    static const std::string sql = "select * from node_inbounds where node_id = $1";
    Result r(nullptr);
    {
        auto binder = *clientPtr << sql;
        binder << *id_ << Mode::Blocking >>
            [&r](const Result &result) { r = result; };
        binder.exec();
    }
    std::vector<NodeInbounds> ret;
    ret.reserve(r.size());
    for (auto const &row : r)
    {
        ret.emplace_back(NodeInbounds(row));
    }
    return ret;
}

void Nodes::getInbounds(const DbClientPtr &clientPtr,
                        const std::function<void(std::vector<NodeInbounds>)> &rcb,
                        const ExceptionCallback &ecb) const
{
    static const std::string sql = "select * from node_inbounds where node_id = $1";
    *clientPtr << sql
               << *id_
               >> [rcb = std::move(rcb)](const Result &r){
                   std::vector<NodeInbounds> ret;
                   ret.reserve(r.size());
                   for (auto const &row : r)
                   {
                       ret.emplace_back(NodeInbounds(row));
                   }
                   rcb(ret);
               }
               >> ecb;
}
